function obtenerPorcentaje(sensorValor) {
    var calibracion = [
        [737, 0],
        [1825, 25],
        [3653, 50],
        [5476, 75],
        [7305, 100]
    ];

    for (var i = 0; i < calibracion.length - 1; i++) {
        var x0 = calibracion[i][0];
        var y0 = calibracion[i][1];
        var x1 = calibracion[i + 1][0];
        var y1 = calibracion[i + 1][1];

        if (sensorValor >= x0 && sensorValor <= x1) {
            var porcentaje = y0 + ((sensorValor - x0) / (x1 - x0)) * (y1 - y0);
            return Math.round(porcentaje * 100) / 100; // Redondea a 2 decimales
        }
    }

    // Fuera de rango
    if (sensorValor < calibracion[0][0]) {
        return 0.0;
    } else if (sensorValor > calibracion[calibracion.length - 1][0]) {
        return 100.0;
    }
}

msg = {
    "valor": msg.pv,
    "porcentaje": obtenerPorcentaje(msg.pv)
}


return {msg: msg, metadata: metadata, msgType: msgType};
